#pragma once
static const char PORTAL_HEAD[] = R"HTML(<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>臺鐵小看板設定</title><style>*{box-sizing:border-box}body{margin:0;background:#111916;color:#f4f6ef;font:16px system-ui}main{max-width:540px;margin:auto;padding:28px 20px}.tag{color:#e2bc65;letter-spacing:3px}h1{font-size:30px}p{color:#b5c4bb;line-height:1.6}label{display:block;margin:18px 0 7px}input,select,button{font:inherit;padding:13px;width:100%;border:1px solid #506158;border-radius:8px;background:#1d2a23;color:white}button{margin:24px 0;background:#e2bc65;color:#162219;font-weight:700}small{color:#b5c4bb}details{margin-top:25px}a{color:#e2bc65}</style><main><span class="tag">TRA · DEPARTURES</span><h1>把車站帶回桌上</h1><p>連上家中 2.4 GHz Wi-Fi，選擇車站。設定會儲存在看板，重新開機仍會保留。</p><form method="post" action="/save">)HTML";
static const char PORTAL_MIDDLE[] = R"HTML(<label>Wi-Fi 密碼</label><input name="password" type="password" maxlength="63" autocomplete="new-password" placeholder="已儲存時留白保留原密碼"><label><input name="open" type="checkbox" style="width:auto"> 這是無密碼的 Wi-Fi</label><label>篩選縣市</label><select id="region"><option value="">全台車站</option></select><label>搜尋站名或代碼</label><input id="search" type="search" placeholder="例如：礁溪、臺北、7210"><label>顯示車站</label><select name="station" id="station" required>)HTML";
static const char PORTAL_TAIL[] = R"HTML(<label>螢幕方向</label><select name="rotation"><option value="0">正常橫向</option><option value="180">上下顛倒（旋轉 180°）</option></select><small>儲存後重新開機套用，觸控方向同步調整。</small><label>方向標示</label><select name="labels"><option value="ns">北上／南下（依站點預設，可反轉）</option><option value="cw">順行／逆行（支線建議使用）</option></select><label>南北方向對調</label><select name="flip"><option value="0">使用站點預設</option><option value="1">交換北上與南下</option></select><p>資料來源：臺鐵官方 OpenData。每 2 分鐘檢查更新，只顯示表定時刻，無即時誤點資訊。</p><label><input name="auto" type="checkbox" style="width:auto"> 每 15 秒輪播兩個方向</label><button>儲存並重新連線</button></form><small>長按板上 GPIO14 按鈕 3 秒，可隨時重新開啟此設定頁。</small></main><script>const s=document.querySelector('#station'),all=[...s.options],region=document.querySelector('#region'),q=document.querySelector('#search');[...new Set(all.map(o=>o.dataset.region))].sort().forEach(r=>region.add(new Option(r,r)));let selected=s.value;s.onchange=()=>selected=s.value;function filter(){s.replaceChildren(...all.filter(o=>(!region.value||o.dataset.region===region.value)&&o.textContent.replaceAll('臺','台').includes(q.value.replaceAll('臺','台'))));if([...s.options].some(o=>o.value===selected))s.value=selected}region.onchange=q.oninput=filter;const current=JSON.parse(document.querySelector('#current').textContent);for(const k of ['labels','flip','rotation'])document.querySelector(`[name="${k}"]`).value=current[k];document.querySelector('[name="auto"]').checked=current.auto;</script></html>)HTML";
